  it('moves a live single-month spending card to the current month', () => {
    // Card was created while viewing 2016-12; it is Live, so it should
    // switch to the current month (2017-01) instead of staying on 2016-12.
    const [compare] = calculateSpendingReportTimeRange({
      compare: '2016-12',
      compareTo: '2016-11',
      isLive: true,
      mode: 'single-month',
    });

    expect(compare).toBe('2017-01');
  });
});

